import{_ as s,C as i,c as a,o as l,aj as g,j as e,G as o,a as c,w as h}from"./chunks/framework.Bfdr4H5E.js";const d="/sk/images/Sideways-Price-Action-1-Area.webp",p="/sk/images/Sideways-Price-Action-2-Area.webp",u="/sk/images/Sideways-Price-Action-3-Area.webp",P=JSON.parse('{"title":"Sideways Price Action Area","description":"","frontmatter":{"outline":"deep","prev":{"text":"How to Spot Institutional Activity With PRICE ACTION","link":"/trading-with-pav/how-to-spot-institutional-activity-with-price-action"},"next":{"text":"Aggressive Initiation","link":"/trading-with-pav/aggressive-initiation"}},"headers":[],"relativePath":"trading-with-pav/sideways-price-action-area.md","filePath":"trading-with-pav/sideways-price-action-area.md"}'),m={name:"trading-with-pav/sideways-price-action-area.md"};function w(y,t,f,A,v,b){const n=i("GraphComment"),r=i("ClientOnly");return l(),a("div",null,[t[0]||(t[0]=g('<h1 id="sideways-price-action-area" tabindex="-1">Sideways Price Action Area <a class="header-anchor" href="#sideways-price-action-area" aria-label="Permalink to &quot;Sideways Price Action Area&quot;">​</a></h1><p>Let’s dive into what is Sideways Price Action Area and how to spot on the chart.</p><ol><li>The biggest differences between <strong>retail traders</strong> (us) and <strong>institutions</strong> is <ul><li><strong>The amount of the trading capital that we manage.</strong></li></ul></li><li><strong>Institutions</strong> have <strong>extreme amounts of capital</strong>, and because of this, they have a problem that we will never have. <ul><li><strong>The problem is simply having too much money.</strong></li></ul></li><li>If they want to <strong>open</strong> a <strong>large trade unnoticed</strong>, <ul><li><strong>They need a lot of time to enter their position.</strong></li><li>They intend to do it <strong>slowly</strong>, <strong>unnoticed</strong>, so <strong>nobody realizes what they are doing</strong>.</li></ul></li><li><strong>If they succeed</strong>, they can enter their <strong>large position without alerting</strong> other <strong>market participants</strong> and without moving the <strong>price</strong> too much.</li></ol><p>If for example a large <strong>Mutual Funds</strong> <strong>institution</strong> started buying vast amounts of the <strong>Bank Nifty instruments</strong> <strong>quickly</strong> and <strong>aggressively</strong>, it would start a lot of <strong>excitement</strong> and a <strong>trend</strong> would <strong>start</strong>.</p><ul><li><p>In this case, the <strong>trend</strong> wouldn’t be their friend because</p><ul><li><strong>They would not be able to fully enter their large trading position.</strong></li><li><strong>At least not for the prices they would like.</strong></li></ul></li><li><p>For this reason, <strong>institutions</strong> need a <strong>lot of time</strong> to enter their <strong>big positions unnoticed</strong>.</p><ul><li><strong>They try to appear as small investors who are randomly placing a lot of relatively small positions in the market.</strong></li><li><strong>The only way they can slowly and discreetly accumulate their positions is in Sideways Price Action Area.</strong></li><li><strong>There they can hide their activity perfectly.</strong></li></ul></li></ul><p>So, next time you see a <strong>Sideways Price Action Area/Channel</strong> don’t assume that it is <strong>boring</strong> and that <strong>nothing</strong> is going on there. You would be most likely wrong.</p><p>A <strong>Sideways Price Action</strong> is a place where <strong>big institutions</strong> are getting ready for <strong>action</strong>.</p><p>That’s why it is so important and why it is among the first things we look for when we analyze any chart. Lets spot the <strong>sideways price action</strong> in the following image.</p><p><img src="'+d+'" alt="Sideways-Price-Action-1-Area"></p><p>The below image has 6 rectangle area spotting sideways area.</p><p><img src="'+p+'" alt="Sideways-Price-Action-2-Area"></p><p>As you can see below <strong>heavy volumes</strong> (shown at right side)have <strong>accumulated</strong> at every <strong>sideways price area</strong> which is <strong>institution accumulating</strong> their <strong>huge position</strong>.</p><p><img src="'+u+'" alt="Sideways-Price-Action-3-Area"></p><ul><li><strong>Sideways Price Action</strong> is a very significant place on all <strong>timeframes</strong>.</li><li>It doesn’t matter if you use a <ul><li><strong>1-min</strong>ute chart,</li><li><strong>30-min</strong>ute chart,</li><li><strong>Daily</strong> chart or</li><li>a <strong>Weekly</strong> chart.</li></ul></li><li>The <strong>logic</strong> is always the same, and that‘s why it works so well with all timeframes.</li><li>We <strong>analyze charts</strong> most often on the <strong>30-min</strong>ute timeframe (<strong>intraday</strong> trades) and <strong>4H or daily</strong> timeframe (<strong>swing</strong> trades).</li></ul><p><strong>Summary</strong>: Look for <strong>Sideways Price Action areas.</strong> Those are very <strong>significant places because institutions</strong> are <strong>accumulating their positions</strong> there**.**</p><p>Always watch for such areas, no matter which timeframe you use. In the next article will continue with <strong>Aggressive Initiation</strong>.</p><h2 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h2>',17)),t[1]||(t[1]=e("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/LBBSdHzBaCA",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""},null,-1)),t[2]||(t[2]=e("p",null,"The above video explains this article in hindi language.",-1)),t[3]||(t[3]=e("h2",{id:"comments",tabindex:"-1"},[c("Comments "),e("a",{class:"header-anchor",href:"#comments","aria-label":'Permalink to "Comments"'},"​")],-1)),o(r,null,{default:h(()=>[o(n)]),_:1})])}const S=s(m,[["render",w]]);export{P as __pageData,S as default};
